var scheduler = new Scheduler();
var resources = new[]
{
    new Resource { Name = "First", Skills = ["CSharp"], Calendar = [] },
    new Resource { Name = "Second", Skills = ["CSharp"], Calendar = [] }
};
var jobs = new[]
{
    new Job { Id = "ignored", RequiredSkill = "", Priority = 1, Duration = TimeSpan.FromHours(1) },
    new Job { Id = "missing", RequiredSkill = "Python", Priority = 1, Duration = TimeSpan.FromHours(1) },
    new Job { Id = "normal", RequiredSkill = "CSharp", Priority = 5, Duration = TimeSpan.FromHours(8) },
    new Job { Id = "urgent", RequiredSkill = "CSharp", Priority = 9, Duration = TimeSpan.FromHours(8) },
    new Job { Id = "long", RequiredSkill = "CSharp", Priority = 9, Duration = TimeSpan.FromHours(9) }
};
var placements = scheduler.PlaceJobs(jobs, resources);
Check.SequenceEqual(new[]
{
    "missing:UNPLACED",
    "normal:First",
    "urgent:First:URGENT",
    "long:First:OT"
}, placements);
